sys_variable_value.value:
(function execute(inputs, outputs) {

  outputs.task_id = sn_ml_di.DocDataExtractorScriptObject.createTask(inputs.task_definition.sys_id, 
                                                                {"displayName" : inputs.name, 
                                                                 "sourceTable" : inputs.source_table_name,
                                                                 "sourceRecord" : inputs.source_record_id,
                                                                 "attachmentIds" : inputs.attachment_ids,
                                                                });
})(inputs, outputs);

